4113:   private static long[] p3ReportNumericCounts(JsonNode node, int depth) {
4114:     int structuralDepth = depth + (node.isContainerNode() ? 1 : 0);
4115:     if (structuralDepth > 64) {
4116:       throw new IllegalArgumentException("P3 callback witness depth");
4117:     }
4118:     long floats = 0, fractions = 0;
4119:     if (node.isNumber()) {
4120:       double number = node.doubleValue();
4121:       if (!Double.isFinite(number)) {
4122:         throw new IllegalArgumentException("P3 nonfinite callback number");
4123:       }
4124:       if (node.isFloatingPointNumber()) {
4125:         floats = 1;
4126:         fractions = number != Math.rint(number) ? 1 : 0;
4127:       }
4128:     }
4129:     if (node.isContainerNode()) {
4130:       for (JsonNode child : node) {
4131:         long[] counts = p3ReportNumericCounts(child, structuralDepth);
4132:         floats += counts[0];
4133:         fractions += counts[1];
4134:       }
4135:     }
4136:     return new long[] {floats, fractions};
4137:   }
